local __chars="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local __lookup={}
for i=1,64 do __lookup[string.sub(__chars,i,i)]=i-1 end
local function __decode(s)
    s=string.gsub(s,"[^ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=]","")
    local result={}
    local i=1
    while i<=#s do
        local a=__lookup[string.sub(s,i,i)] or 0
        local b=__lookup[string.sub(s,i+1,i+1)] or 0
        local c=__lookup[string.sub(s,i+2,i+2)] or 0
        local d=__lookup[string.sub(s,i+3,i+3)] or 0
        local n=a*262144+b*4096+c*64+d
        local b1=(n-n%65536)/65536
        local b2=((n%65536)-(n%256))/256
        local b3=n%256
        result[#result+1]=string.char(b1)
        if string.sub(s,i+2,i+2)~="=" then result[#result+1]=string.char(b2) end
        if string.sub(s,i+3,i+3)~="=" then result[#result+1]=string.char(b3) end
        i=i+4
    end
    return table.concat(result)
end
local function __xor(s)
    local r={}
    local kl=#__key
    for i=1,#s do
        local b=string.byte(s,i)
        local k=__key[((i-1)%kl)+1]
        r[#r+1]=string.char(b~k)
    end
    return table.concat(r)
end
local __src=__xor(__decode(__b64))
local __fn=loadstring(__src)
if __fn then __fn() else warn("[ERR] loadstring failed") end
